        return amount_;
    }

function setAavePoolDataProvider(address value_) public onlyOwner {
        require(value_ != address(0), "DR: invalid Aave pool data provider address");

        aavePoolDataProvider = value_;

        emit AavePoolDataProviderSet(value_);
    }
